import {clone} from '../document/model.js';
import {evaluated,setProperty,activeTracks,allTracks} from '../animation/evaluate.js';
import {fitMesh} from './contour.js';
export function currentMesh(n,time){const mesh=evaluated(n,time).mesh,tracks=activeTracks(n,time);return mesh?.contour&&!tracks.mesh?.length&&tracks.nodes?.length&&mesh.geometryTime!==time?fitMesh(n,time,mesh):mesh;}
export function editMesh(n,time,edit,topology=false){const keys=allTracks(n).flatMap(tracks=>tracks.mesh||[]),cuts=(n.blockCuts||[]).filter(c=>c.values.mesh);if(topology&&(keys.length||cuts.length)){const base=n.mesh?edit(clone(n.mesh)):undefined,values=keys.map(k=>edit(clone(k.value))),held=cuts.map(c=>edit(clone(c.values.mesh)));if(base)n.mesh=base;keys.forEach((k,i)=>k.value=values[i]);cuts.forEach((c,i)=>c.values.mesh=held[i]);}else setProperty(n,'mesh',edit(clone(currentMesh(n,time))),time);}